package com.example.onlineshop.catalog.api;
import com.example.onlineshop.catalog.application.*; import com.example.onlineshop.catalog.domain.Product; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.media.*; import io.swagger.v3.oas.annotations.responses.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.net.URI; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/products") class ProductController {
 private final CatalogService catalog; ProductController(CatalogService catalog){this.catalog=catalog;}
 @Operation(summary="Create a product") @ApiResponses({@ApiResponse(responseCode="201",description="Created"),@ApiResponse(responseCode="400",description="Malformed request",content=@Content(mediaType="application/problem+json",schema=@Schema(implementation=ProblemDetail.class))),@ApiResponse(responseCode="422",description="Invalid product",content=@Content(mediaType="application/problem+json",schema=@Schema(implementation=ProblemDetail.class)))})
 @PostMapping ResponseEntity<ProductResponse> create(@Valid @RequestBody CreateProductRequest r){var p=catalog.create(r.name,r.description,r.price,r.currency,r.stockQuantity);return ResponseEntity.created(URI.create("/api/v1/products/"+p.id())).body(ProductResponse.from(p));}
 @Operation(summary="Get a product") @ApiResponses({@ApiResponse(responseCode="200",description="Product"),@ApiResponse(responseCode="400",description="Malformed id",content=@Content(mediaType="application/problem+json",schema=@Schema(implementation=ProblemDetail.class))),@ApiResponse(responseCode="404",description="Not found",content=@Content(mediaType="application/problem+json",schema=@Schema(implementation=ProblemDetail.class)))})
 @GetMapping("/{productId}") ProductResponse get(@PathVariable UUID productId){return ProductResponse.from(catalog.get(productId));}
 @Operation(summary="List products") @ApiResponses({@ApiResponse(responseCode="200",description="Product page"),@ApiResponse(responseCode="422",description="Invalid pagination",content=@Content(mediaType="application/problem+json",schema=@Schema(implementation=ProblemDetail.class)))})
 @GetMapping PageResponse list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var result=catalog.list(page,size);return new PageResponse(result.content().stream().map(ProductResponse::from).toList(),page,size,result.total());}
 record CreateProductRequest(@NotBlank @Size(max=160) String name,@NotNull @Size(max=2000) String description,@NotNull @DecimalMin("0.00") @Digits(integer=17,fraction=2) BigDecimal price,@NotBlank @Pattern(regexp="[A-Z]{3}") String currency,@PositiveOrZero int stockQuantity){}
 record ProductResponse(UUID id,String name,String description,String price,String currency,int stockQuantity,Instant createdAt,Instant updatedAt){static ProductResponse from(Product p){return new ProductResponse(p.id(),p.name(),p.description(),p.price().setScale(2).toPlainString(),p.currency(),p.stockQuantity(),p.createdAt(),p.updatedAt());}}
 record PageResponse(List<ProductResponse> content,int page,int size,long totalElements){}
}
